// generated once, at the start of the attempt, and reused for every retry
const idempotencyKey = crypto.randomUUID();

async function placeOrder(basket, attempt = 1) {
  try {
    return await paymentClient.post('/orders', basket, {
      headers: { 'Idempotency-Key': idempotencyKey },
      timeout: 4000
    });
  } catch (error) {
    if (!isRetryable(error) || attempt >= 3) throw error;
    await backoff(attempt);
    return placeOrder(basket, attempt + 1);
  }
}
